import React, { useState, useEffect } from 'react';
import { 
  Bus, 
  MapPin, 
  Clock, 
  DollarSign, 
  Ticket, 
  PlusCircle, 
  Image as ImageIcon, 
  CheckCircle,
  TrendingUp,
  Users
} from 'lucide-react';

// All 64 Districts of Bangladesh
const BANGLADESH_DISTRICTS = [
  "Bagerhat", "Bandarban", "Barguna", "Barishal", "Bhola", "Bogra", "Brahmanbaria", "Chandpur", 
  "Chattogram", "Chuadanga", "Cumilla", "Cox's Bazar", "Dhaka", "Dinajpur", "Faridpur", "Feni", 
  "Gaibandha", "Gazipur", "Gopalganj", "Habiganj", "Jamalpur", "Jashore", "Jhalokathi", "Jhenaidah", 
  "Joypurhat", "Khagrachhari", "Khulna", "Kishoreganj", "Kurigram", "Kushtia", "Lakshmipur", "Lalmonirhat", 
  "Madaripur", "Magura", "Manikganj", "Meherpur", "Moulvibazar", "Munshiganj", "Mymensingh", "Naogaon", 
  "Narail", "Narayanganj", "Narsingdi", "Natore", "Nawabganj", "Netrokona", "Nilphamari", "Noakhali", 
  "Pabna", "Panchagarh", "Patuakhali", "Pirojpur", "Rajbari", "Rajshahi", "Rangamati", "Rangpur", 
  "Satkhira", "Shariatpur", "Sherpur", "Sirajganj", "Sunamganj", "Sylhet", "Tangail", "Thakurgaon"
];

export default function DashboardSystem() {
  const [activeTab, setActiveTab] = useState('admin-dashboard'); // 'admin-dashboard', 'create-route', 'user-panel'
  
  // Dynamic Shared States (Initialized empty - No Dummy Items)
  const [routes, setRoutes] = useState([]);
  const [bookings, setBookings] = useState([]);

  // Load Saved Data from LocalStorage on mount
  useEffect(() => {
    const savedRoutes = JSON.parse(localStorage.getItem('app_bus_routes') || '[]');
    const savedBookings = JSON.parse(localStorage.getItem('app_bus_bookings') || '[]');
    setRoutes(savedRoutes);
    setBookings(savedBookings);
  }, []);

  // Save changes persistently
  const saveRoutesToStorage = (updatedRoutes) => {
    setRoutes(updatedRoutes);
    localStorage.setItem('app_bus_routes', JSON.stringify(updatedRoutes));
  };

  const saveBookingsToStorage = (updatedBookings) => {
    setBookings(updatedBookings);
    localStorage.setItem('app_bus_bookings', JSON.stringify(updatedBookings));
  };

  // --- STATS CALCULATIONS ---
  const activeRoutesCount = routes.length;
  const totalTicketsSold = bookings.reduce((sum, b) => sum + b.seatsBooked, 0);
  const totalRevenue = bookings.reduce((sum, b) => sum + b.totalPaid, 0);

  // --- CREATE ROUTE FORM STATE ---
  const [routeForm, setRouteForm] = useState({
    operatorName: '',
    fromDistrict: 'Dhaka',
    toDistrict: 'Chattogram',
    busType: 'AC Deluxe',
    fare: '',
    totalSeats: '40',
    arrivalTime: '',
    departureTime: '',
    estimatedHours: '',
    images: []
  });

  const [imagePreviews, setImagePreviews] = useState([]);
  const [routeSuccessMsg, setRouteSuccessMsg] = useState('');

  // Handle Multi-Image Upload
  const handleImageUpload = (e) => {
    const files = Array.from(e.target.files);
    const newPreviews = [];

    files.forEach((file) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        newPreviews.push(reader.result);
        if (newPreviews.length === files.length) {
          setImagePreviews((prev) => [...prev, ...newPreviews]);
          setRouteForm((prev) => ({ ...prev, images: [...prev.images, ...newPreviews] }));
        }
      };
      reader.readAsDataURL(file);
    });
  };

  // Create New Route Handler
  const handleRouteSubmit = (e) => {
    e.preventDefault();
    if (!routeForm.fare || !routeForm.departureTime || !routeForm.arrivalTime) {
      alert("Please fill in all mandatory fields.");
      return;
    }

    const newRoute = {
      id: 'RTE-' + Math.floor(1000 + Math.random() * 9000),
      ...routeForm,
      fare: parseFloat(routeForm.fare),
      totalSeats: parseInt(routeForm.totalSeats, 10),
      availableSeats: parseInt(routeForm.totalSeats, 10),
      createdAt: new Date().toISOString().split('T')[0]
    };

    const updatedRoutes = [newRoute, ...routes];
    saveRoutesToStorage(updatedRoutes);

    setRouteSuccessMsg('Route successfully created and published!');
    setTimeout(() => {
      setRouteSuccessMsg('');
      setActiveTab('admin-dashboard');
    }, 1500);

    // Reset Form
    setRouteForm({
      operatorName: '',
      fromDistrict: 'Dhaka',
      toDistrict: 'Chattogram',
      busType: 'AC Deluxe',
      fare: '',
      totalSeats: '40',
      arrivalTime: '',
      departureTime: '',
      estimatedHours: '',
      images: []
    });
    setImagePreviews([]);
  };

  // --- USER BUY TICKET HANDLER ---
  const handleBuyTicket = (route, seatCount) => {
    if (route.availableSeats < seatCount) {
      alert("Not enough seats available!");
      return;
    }

    const ticketPrice = route.fare;
    const totalPaid = ticketPrice * seatCount;

    // 1. Record New Booking
    const newBooking = {
      id: 'BKG-' + Math.floor(100000 + Math.random() * 900000),
      routeId: route.id,
      from: route.fromDistrict,
      to: route.toDistrict,
      seatsBooked: seatCount,
      ticketPrice: ticketPrice,
      totalPaid: totalPaid,
      bookedAt: new Date().toLocaleString()
    };

    const updatedBookings = [newBooking, ...bookings];
    saveBookingsToStorage(updatedBookings);

    // 2. Update Remaining Seats on Route
    const updatedRoutes = routes.map((r) => {
      if (r.id === route.id) {
        return { ...r, availableSeats: r.availableSeats - seatCount };
      }
      return r;
    });
    saveRoutesToStorage(updatedRoutes);

    alert(`Success! Booked ${seatCount} ticket(s) for ৳${totalPaid}. Revenue added to Admin Panel!`);
  };

  return (
    <div style={styles.container}>
      {/* GLOBAL NAVBAR / HEADER */}
      <nav style={styles.navbar}>
        <div style={styles.brand}>
          <Bus size={24} color="#ea580c" />
          <span style={styles.brandText}>OnlineBus BD</span>
        </div>
        <div style={styles.navLinks}>
          <button 
            style={{ ...styles.navBtn, ...(activeTab === 'admin-dashboard' ? styles.activeNavBtn : {}) }}
            onClick={() => setActiveTab('admin-dashboard')}
          >
            Admin Dashboard
          </button>
          <button 
            style={{ ...styles.navBtn, ...(activeTab === 'create-route' ? styles.activeNavBtn : {}) }}
            onClick={() => setActiveTab('create-route')}
          >
            + Create Route
          </button>
          <button 
            style={{ ...styles.navBtn, ...(activeTab === 'user-panel' ? styles.activeNavBtn : {}) }}
            onClick={() => setActiveTab('user-panel')}
          >
            User Booking Panel
          </button>
        </div>
      </nav>

      <main style={styles.content}>

        {/* ==================== 1. ADMIN DASHBOARD ==================== */}
        {activeTab === 'admin-dashboard' && (
          <div>
            <h2 style={styles.pageTitle}>Admin Management Dashboard</h2>
            
            {/* REAL-TIME STATS COUNTERS */}
            <div style={styles.statsGrid}>
              <div style={styles.statCard}>
                <div style={styles.statHeader}>
                  <span style={styles.statTitle}>Active Bus Routes</span>
                  <Bus size={20} color="#ea580c" />
                </div>
                <div style={styles.statValue}>{activeRoutesCount}</div>
                <div style={styles.statSubtext}>Live active operational routes</div>
              </div>

              <div style={styles.statCard}>
                <div style={styles.statHeader}>
                  <span style={styles.statTitle}>Sold Tickets</span>
                  <Ticket size={20} color="#16a34a" />
                </div>
                <div style={styles.statValue}>{totalTicketsSold}</div>
                <div style={styles.statSubtext}>Total seat bookings completed</div>
              </div>

              <div style={styles.statCard}>
                <div style={styles.statHeader}>
                  <span style={styles.statTitle}>Total Revenue</span>
                  <DollarSign size={20} color="#2563eb" />
                </div>
                <div style={styles.statValue}>৳ {totalRevenue.toLocaleString()}</div>
                <div style={styles.statSubtext}>Calculated real-time from purchases</div>
              </div>
            </div>

            {/* LIVE ROUTES TABLE IN ADMIN PANEL */}
            <div style={styles.sectionCard}>
              <h3 style={styles.sectionTitle}>Active Route Directory</h3>
              {routes.length === 0 ? (
                <div style={styles.emptyState}>No routes created yet. Click "+ Create Route" to add your first route.</div>
              ) : (
                <table style={styles.table}>
                  <thead>
                    <tr style={styles.tableHeaderRow}>
                      <th style={styles.th}>Route ID</th>
                      <th style={styles.th}>Operator</th>
                      <th style={styles.th}>Route</th>
                      <th style={styles.th}>Type</th>
                      <th style={styles.th}>Schedule</th>
                      <th style={styles.th}>Fare</th>
                      <th style={styles.th}>Seat Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {routes.map((r) => (
                      <tr key={r.id} style={styles.tableRow}>
                        <td style={styles.td}><strong>{r.id}</strong></td>
                        <td style={styles.td}>{r.operatorName || 'Standard Express'}</td>
                        <td style={styles.td}>{r.fromDistrict} ➔ {r.toDistrict}</td>
                        <td style={styles.td}>{r.busType}</td>
                        <td style={styles.td}>{r.departureTime} - {r.arrivalTime} ({r.estimatedHours} hrs)</td>
                        <td style={styles.td}>৳ {r.fare}</td>
                        <td style={styles.td}>{r.availableSeats} / {r.totalSeats} Available</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        )}

        {/* ==================== 2. CREATE ROUTE FORM ==================== */}
        {activeTab === 'create-route' && (
          <div style={styles.formCard}>
            <h2 style={styles.pageTitle}>Create New Bus Route</h2>
            {routeSuccessMsg && (
              <div style={styles.successBanner}>
                <CheckCircle size={18} /> {routeSuccessMsg}
              </div>
            )}

            <form onSubmit={handleRouteSubmit} style={styles.formGrid}>
              
              {/* Bus Operator Name */}
              <div style={styles.inputGroup}>
                <label style={styles.label}>Bus / Operator Name</label>
                <input 
                  type="text" 
                  placeholder="e.g. Hanif Enterprise, Green Line"
                  value={routeForm.operatorName}
                  onChange={(e) => setRouteForm({ ...routeForm, operatorName: e.target.value })}
                  style={styles.input}
                  required
                />
              </div>

              {/* Bus Type */}
              <div style={styles.inputGroup}>
                <label style={styles.label}>3. Bus Type</label>
                <select 
                  value={routeForm.busType}
                  onChange={(e) => setRouteForm({ ...routeForm, busType: e.target.value })}
                  style={styles.select}
                >
                  <option value="AC Business Class">AC Business Class</option>
                  <option value="AC Deluxe">AC Deluxe</option>
                  <option value="Non-AC Economy">Non-AC Economy</option>
                  <option value="Double Decker AC">Double Decker AC</option>
                </select>
              </div>

              {/* Route From (District) */}
              <div style={styles.inputGroup}>
                <label style={styles.label}>2. Route From (Origin District)</label>
                <select 
                  value={routeForm.fromDistrict}
                  onChange={(e) => setRouteForm({ ...routeForm, fromDistrict: e.target.value })}
                  style={styles.select}
                >
                  {BANGLADESH_DISTRICTS.map((d) => (
                    <option key={d} value={d}>{d}</option>
                  ))}
                </select>
              </div>

              {/* Route To (District) */}
              <div style={styles.inputGroup}>
                <label style={styles.label}>2. Route To (Destination District)</label>
                <select 
                  value={routeForm.toDistrict}
                  onChange={(e) => setRouteForm({ ...routeForm, toDistrict: e.target.value })}
                  style={styles.select}
                >
                  {BANGLADESH_DISTRICTS.map((d) => (
                    <option key={d} value={d}>{d}</option>
                  ))}
                </select>
              </div>

              {/* Fare */}
              <div style={styles.inputGroup}>
                <label style={styles.label}>4. Ticket Fare (BDT ৳)</label>
                <input 
                  type="number" 
                  placeholder="e.g. 1200"
                  value={routeForm.fare}
                  onChange={(e) => setRouteForm({ ...routeForm, fare: e.target.value })}
                  style={styles.input}
                  required
                />
              </div>

              {/* Total Seats */}
              <div style={styles.inputGroup}>
                <label style={styles.label}>5. Total Seats</label>
                <input 
                  type="number" 
                  placeholder="e.g. 40"
                  value={routeForm.totalSeats}
                  onChange={(e) => setRouteForm({ ...routeForm, totalSeats: e.target.value })}
                  style={styles.input}
                  required
                />
              </div>

              {/* Departure Time */}
              <div style={styles.inputGroup}>
                <label style={styles.label}>7. Bus Departure Time</label>
                <input 
                  type="time" 
                  value={routeForm.departureTime}
                  onChange={(e) => setRouteForm({ ...routeForm, departureTime: e.target.value })}
                  style={styles.input}
                  required
                />
              </div>

              {/* Arrival Time */}
              <div style={styles.inputGroup}>
                <label style={styles.label}>6. Bus Arrival Time to Terminal</label>
                <input 
                  type="time" 
                  value={routeForm.arrivalTime}
                  onChange={(e) => setRouteForm({ ...routeForm, arrivalTime: e.target.value })}
                  style={styles.input}
                  required
                />
              </div>

              {/* Estimated Journey Hour */}
              <div style={styles.inputGroup}>
                <label style={styles.label}>8. Estimated Journey Hours</label>
                <input 
                  type="number" 
                  step="0.5"
                  placeholder="e.g. 6.5"
                  value={routeForm.estimatedHours}
                  onChange={(e) => setRouteForm({ ...routeForm, estimatedHours: e.target.value })}
                  style={styles.input}
                  required
                />
              </div>

              {/* Multiple Bus Pictures */}
              <div style={{ ...styles.inputGroup, gridColumn: 'span 2' }}>
                <label style={styles.label}>1. Add Multiple Bus Pictures</label>
                <input 
                  type="file" 
                  multiple 
                  accept="image/*"
                  onChange={handleImageUpload}
                  style={styles.fileInput}
                />
                
                {/* Image Previews */}
                {imagePreviews.length > 0 && (
                  <div style={styles.previewContainer}>
                    {imagePreviews.map((imgSrc, idx) => (
                      <img key={idx} src={imgSrc} alt="Preview" style={styles.previewImg} />
                    ))}
                  </div>
                )}
              </div>

              <button type="submit" style={styles.submitBtn}>
                <PlusCircle size={18} /> Publish New Route
              </button>
            </form>
          </div>
        )}

        {/* ==================== 3. USER BOOKING PANEL ==================== */}
        {activeTab === 'user-panel' && (
          <div>
            <h2 style={styles.pageTitle}>Passenger Ticket Booking</h2>
            <p style={styles.subtext}>Browse routes configured live by the Admin and purchase tickets.</p>

            {routes.length === 0 ? (
              <div style={styles.emptyState}>No bus routes are available for booking at the moment.</div>
            ) : (
              <div style={styles.userRouteGrid}>
                {routes.map((r) => (
                  <div key={r.id} style={styles.routeCard}>
                    {/* Bus Image Carousel/Preview */}
                    {r.images && r.images.length > 0 ? (
                      <img src={r.images[0]} alt="Bus" style={styles.cardBusImg} />
                    ) : (
                      <div style={styles.placeholderImg}>
                        <Bus size={40} color="#71717a" />
                      </div>
                    )}

                    <div style={styles.cardBody}>
                      <div style={styles.cardHeader}>
                        <h3 style={styles.operatorTitle}>{r.operatorName || 'Express Bus'}</h3>
                        <span style={styles.typeBadge}>{r.busType}</span>
                      </div>

                      <div style={styles.routeLine}>
                        <MapPin size={16} color="#ea580c" />
                        <strong>{r.fromDistrict}</strong> ➔ <strong>{r.toDistrict}</strong>
                      </div>

                      <div style={styles.scheduleDetails}>
                        <div><Clock size={14} /> Dep: {r.departureTime}</div>
                        <div>Arr: {r.arrivalTime}</div>
                        <div>Dur: {r.estimatedHours} hrs</div>
                      </div>

                      <div style={styles.cardFooter}>
                        <div>
                          <span style={styles.farePrice}>৳ {r.fare}</span>
                          <span style={styles.seatCount}> ({r.availableSeats} seats left)</span>
                        </div>
                        <button 
                          style={styles.bookBtn}
                          disabled={r.availableSeats === 0}
                          onClick={() => handleBuyTicket(r, 1)}
                        >
                          {r.availableSeats > 0 ? 'Buy 1 Ticket' : 'Sold Out'}
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

      </main>
    </div>
  );
}

// INLINE STYLES FOR CLEAN RESPONSIVE LAYOUT
const styles = {
  container: { backgroundColor: '#18181b', minHeight: '100vh', color: '#ffffff', fontFamily: 'sans-serif' },
  navbar: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '16px 32px', backgroundColor: '#27272a', borderBottom: '1px solid #3f3f46' },
  brand: { display: 'flex', alignItems: 'center', gap: '10px' },
  brandText: { fontSize: '1.2rem', fontWeight: 'bold' },
  navLinks: { display: 'flex', gap: '12px' },
  navBtn: { padding: '8px 16px', borderRadius: '8px', border: 'none', backgroundColor: '#3f3f46', color: '#ffffff', cursor: 'pointer', fontWeight: '600' },
  activeNavBtn: { backgroundColor: '#ea580c' },
  content: { padding: '32px', maxWidth: '1200px', margin: '0 auto' },
  pageTitle: { margin: '0 0 8px 0', fontSize: '1.6rem', color: '#ffffff' },
  subtext: { color: '#a1a1aa', marginBottom: '24px' },
  statsGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '20px', marginBottom: '32px' },
  statCard: { backgroundColor: '#27272a', padding: '20px', borderRadius: '12px', border: '1px solid #3f3f46' },
  statHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  statTitle: { fontSize: '0.875rem', color: '#a1a1aa' },
  statValue: { fontSize: '2rem', fontWeight: 'bold', margin: '12px 0 4px 0' },
  statSubtext: { fontSize: '0.75rem', color: '#71717a' },
  sectionCard: { backgroundColor: '#27272a', padding: '24px', borderRadius: '12px', border: '1px solid #3f3f46' },
  sectionTitle: { margin: '0 0 16px 0', fontSize: '1.2rem' },
  table: { width: '100%', borderCollapse: 'collapse', textAlign: 'left' },
  tableHeaderRow: { borderBottom: '1px solid #3f3f46' },
  th: { padding: '12px', color: '#a1a1aa', fontSize: '0.85rem' },
  td: { padding: '12px', borderBottom: '1px solid #27272a', fontSize: '0.9rem' },
  tableRow: { borderBottom: '1px solid #3f3f46' },
  emptyState: { padding: '32px', textAlign: 'center', color: '#a1a1aa', backgroundColor: '#27272a', borderRadius: '12px' },
  formCard: { backgroundColor: '#27272a', padding: '32px', borderRadius: '16px', border: '1px solid #3f3f46', maxWidth: '800px', margin: '0 auto' },
  formGrid: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', marginTop: '20px' },
  inputGroup: { display: 'flex', flexDirection: 'column', gap: '6px' },
  label: { fontSize: '0.8rem', fontWeight: '600', color: '#d4d4d8' },
  input: { padding: '10px', borderRadius: '8px', border: '1px solid #3f3f46', backgroundColor: '#18181b', color: '#ffffff' },
  select: { padding: '10px', borderRadius: '8px', border: '1px solid #3f3f46', backgroundColor: '#18181b', color: '#ffffff' },
  fileInput: { padding: '8px', borderRadius: '8px', backgroundColor: '#18181b', border: '1px solid #3f3f46', color: '#a1a1aa' },
  previewContainer: { display: 'flex', gap: '10px', marginTop: '10px', flexWrap: 'wrap' },
  previewImg: { width: '80px', height: '60px', objectFit: 'cover', borderRadius: '6px', border: '1px solid #ea580c' },
  submitBtn: { gridColumn: 'span 2', padding: '12px', borderRadius: '8px', border: 'none', backgroundColor: '#ea580c', color: '#ffffff', fontWeight: 'bold', cursor: 'pointer', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '8px', marginTop: '12px' },
  successBanner: { backgroundColor: '#14532d', color: '#86efac', padding: '12px', borderRadius: '8px', display: 'flex', alignItems: 'center', gap: '8px' },
  userRouteGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '20px' },
  routeCard: { backgroundColor: '#27272a', borderRadius: '12px', border: '1px solid #3f3f46', overflow: 'hidden' },
  cardBusImg: { width: '100%', height: '160px', objectFit: 'cover' },
  placeholderImg: { width: '100%', height: '160px', backgroundColor: '#18181b', display: 'flex', alignItems: 'center', justifyContent: 'center' },
  cardBody: { padding: '16px' },
  cardHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' },
  operatorTitle: { margin: 0, fontSize: '1.1rem' },
  typeBadge: { backgroundColor: '#3f3f46', padding: '4px 8px', borderRadius: '4px', fontSize: '0.75rem' },
  routeLine: { display: 'flex', alignItems: 'center', gap: '6px', margin: '12px 0', fontSize: '0.95rem' },
  scheduleDetails: { display: 'flex', justifyContent: 'space-between', fontSize: '0.8rem', color: '#a1a1aa', marginBottom: '16px' },
  cardFooter: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderTop: '1px solid #3f3f46', paddingTop: '12px' },
  farePrice: { fontSize: '1.2rem', fontWeight: 'bold', color: '#16a34a' },
  seatCount: { fontSize: '0.75rem', color: '#a1a1aa' },
  bookBtn: { backgroundColor: '#ea580c', color: '#ffffff', border: 'none', padding: '8px 14px', borderRadius: '6px', fontWeight: '600', cursor: 'pointer' }
};
